cd $(git rev-parse --show-toplevel) && cat > internal/builtin/zz_tmp_collision_e2e_test.go <<'EOF'
package builtin

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/getkin/kin-openapi/openapi3"
	"github.com/stretchr/testify/require"
	"github.com/wojons/muster/pkg/cmdstore"
	"github.com/wojons/muster/pkg/generator"
)

const collisionSpec = `{
  "openapi": "3.0.0",
  "info": {"title": "collide", "version": "1.0.0"},
  "servers": [{"url": "http://example.invalid"}],
  "paths": {
    "/things": {
      "post": {
        "operationId": "createThing",
        "tags": ["things"],
        "parameters": [
          {"name": "output", "in": "query", "schema": {"type": "string"}},
          {"name": "raw", "in": "query", "schema": {"type": "string"}},
          {"name": "body", "in": "query", "schema": {"type": "string"}}
        ],
        "requestBody": {
          "content": {"application/json": {"schema": {"type": "object", "properties": {
            "output": {"type": "string"},
            "raw": {"type": "string"},
            "body": {"type": "string"}
          }}}}
        },
        "responses": {"200": {"description": "ok"}}
      }
    }
  }
}`

func TestTmpCollisionEndToEnd(t *testing.T) {
	loader := openapi3.NewLoader()
	doc, err := loader.LoadFromData([]byte(collisionSpec))
	require.NoError(t, err)
	require.NoError(t, doc.Validate(context.Background()))

	gen, err := generator.NewGenerator(generator.Config{AppName: "openapi-cli", BaseURL: "http://example.invalid", DefaultFormat: "table", SupportedFormats: []string{"table", "json", "yaml"}})
	require.NoError(t, err)

	var commands []*cobra.Command
	require.NotPanics(t, func() {
		commands, err = gen.GenerateCommands(doc)
	})
	require.NoError(t, err)
	require.NotEmpty(t, commands)

	meta, err := commandsToMetadata(commands, "spec.json", "http://example.invalid", doc, []byte(collisionSpec))
	require.NoError(t, err)
	require.NotEmpty(t, meta.Commands, "generated command store must not be empty")

	// dump persisted flags
	for _, c := range meta.Commands {
		t.Logf("command %s %s %s", c.Name, c.Method, c.Path)
		for _, f := range c.Flags {
			t.Logf("  flag %-12s kind=%-8s json=%s", f.Name, f.Kind, f.JSONName)
		}
	}

	// reload through the loader
	var srv *httptest.Server
	var gotQuery map[string][]string
	var gotBody []byte
	srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotQuery = r.URL.Query()
		gotBody, _ = io.ReadAll(r.Body)
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	defer srv.Close()

	l := NewLoader()
	reloaded, err := l.LoadCommands(meta, srv.URL)
	require.NoError(t, err)
	require.NotEmpty(t, reloaded)

	var target *cobra.Command
	for _, c := range reloaded {
		if c.Name() == "create-thing" || c.Name() == "createThing" {
			target = c
		}
	}
	require.NotNil(t, target, "reloaded command missing")
	require.NotNil(t, target.Flag("output"))
	require.NotNil(t, target.Flag("raw"))
	require.NotNil(t, target.Flag("body"))
	require.NotNil(t, target.Flag("output-2"))
	require.NotNil(t, target.Flag("raw-2"))
	require.NotNil(t, target.Flag("body-2"))

	target.SetOut(io.Discard)
	target.SetErr(io.Discard)
	require.NoError(t, target.Flags().Set("output-2", "OUTVAL"))
	require.NoError(t, target.Flags().Set("raw-2", "RAWVAL"))
	require.NoError(t, target.Flags().Set("body-2", "BODYVAL"))
	require.NoError(t, target.Execute())

	b, _ := json.Marshal(gotQuery)
	t.Logf("QUERY=%s BODY=%s", string(b), string(gotBody))
}
EOF
go test -count=1 -run TestTmpCollisionEndToEnd -v ./internal/builtin/ 2>&1 | tail -60

