	require.NotPanics(t, func() { cmds, err = gen.GenerateCommands(doc) })
	require.NoError(t, err)

	var target *cobra.Command
	for _, g := range cmds {
		for _, c := range g.Commands() {
			if c.Name() == "create-thing" {
				target = c
			}
		}
	}
	require.NotNil(t, target)
